class Graph:
    def __init__(self):
        self.graph = {}

    def add_vertex(self, vertex):
        if vertex not in self.graph:
            self.graph[vertex] = []

    def add_edge(self, vertex1, vertex2):
        self.graph[vertex1].append(vertex2)
        self.graph[vertex2].append(vertex1)

    def dijkstra(self, start, end):
        dist = {vertex: float("inf") for vertex in self.graph}
        prev = {vertex: None for vertex in self.graph}
        dist[start] = 0

        pq = [(0, start)]
        while pq:
            dist_to_vertex, vertex = heapq.heappop(pq)
            if dist_to_vertex < dist[vertex]:
                continue
            for neighbor in self.graph[vertex]:
                dist_to_neighbor = dist_to_vertex + 1
                if dist_to_neighbor < dist[neighbor]:
                    dist[neighbor] = dist_to_neighbor
                    prev[neighbor] = vertex
                    heapq.heappush(pq, (dist_to_neighbor, neighbor))
        return dist, prev
